def run(context):
    results = []
    for run in context['enhanced_runs']:
        for stock in context['filtered_stocks']:
            if stock['run_id'] == run['run_id']:
                results.append({
                    'run_id': run['run_id'],
                    'symbol': stock['symbol'],
                    'issue': 'Potential missing data or diagnostic tool mismatch.'
                })
    return results

def run(context):
    holdings = context['holdings']
    eod_prices = context['eod_prices']
    exposure = {}

    for symbol, holding in holdings.items():
        if symbol in eod_prices:
            market_value = holding['qty'] * eod_prices[symbol]['close']
            exposure[symbol] = {
                'market_value': market_value,
                'change_pct': eod_prices[symbol]['change_pct']
            }
    return {'exposure_summary': exposure}
